from pydantic import Field
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    model_config = SettingsConfigDict(
        env_file=".env",
        env_file_encoding="utf-8",
        case_sensitive=True,
        extra="ignore"
    )

    VK_TOKEN: str = Field(...)
    GROUP_ID: str | None = Field(default=None)

    API_BASE_URL: str = Field(...)
    API_FIND_BY_ID_PARTY_ENDPOINT: str = Field(
        default="/api/v1.0/portal/dadata/find-by-id-party/"
    )
    API_USERNAME: str = Field(...)
    API_PASSWORD: str = Field(...)
    API_TOKEN_ENDPOINT: str = Field(
        default="/api/token"
    )
    API_REFRESH_ENDPOINT: str = Field(
        default="/api/token/refresh"
    )

    LOG_LEVEL: str = Field(default="INFO")

    @field_validator("API_BASE_URL")
    @classmethod
    def strip_base_url(cls, v: str) -> str:
        return v.rstrip("/")

    @field_validator(
        "API_FIND_BY_ID_PARTY_ENDPOINT",
        "API_TOKEN_ENDPOINT",
        "API_REFRESH_ENDPOINT"
    )
    @classmethod
    def normalize_endpoint(cls, v: str) -> str:
        v = v.strip()
        if not v.startswith("/"):
            v = "/" + v
        if v != "/" and v.endswith("/"):
            v = v.rstrip("/")
        return v


