        return (int(s[:-1]) % 11) % 10 == int(s[-1])

    def check_ogrnip_15(s: str) -> bool:
        return (int(s[:-1]) % 13) % 10 == int(s[-1])

    if length == 10:
        return check_inn_10(text)
    elif length == 12:
        return check_inn_12(text)
    elif length == 13:
